import{_ as l,a0 as o,w as r,s as p,ao as d,I as n,x as s,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"使用命令行生成高强度密码 | LCTT x X-CMD","titleTemplate":false,"description":"使用命令行生成高强度密码 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用命令行生成高强度密码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用命令行生成高强度密码 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161102 Generate a strong password from the command line","title":"使用命令行生成高强度密码","tag":"201611","desc":""},"relativePath":"201611/20161102 Generate a strong password from the command line.md","filePath":"[post].md"}'),h={name:"201611/20161102 Generate a strong password from the command line.md"};function g(c,e,m,u,b,k){const a=o("Link");return r(),p("div",null,[e[13]||(e[13]=d(`<h1 id="使用命令行生成高强度密码" tabindex="-1">使用命令行生成高强度密码 <a class="header-anchor" href="#使用命令行生成高强度密码" aria-label="Permalink to “使用命令行生成高强度密码”">​</a></h1><p><img src="https://www.rosehosting.com/blog/wp-content/uploads/2016/10/generate-a-strong-password-from-the-command-line.jpg" alt="generate-a-strong-password-from-the-command-line"></p><p>设置一个高强度的密码是非常重要的，这样才能够很好的保护自己的账号或者服务器以及确保自己的数据的安全。通常来说，一个高强度密码至少有 14 个字符，包括大小写字母、数字和特殊字符，并且要牢记永远不用那些字典中的单词。使用长密码比短密码要来的安全，因为密码越长越难猜测。在本文中，我将给你介绍几个不同方法，让你可以在 Linux 命令行下生成一个高强度密码。</p><h3 id="使用-openssl-生成高强度密码" tabindex="-1">使用 openssl 生成高强度密码 <a class="header-anchor" href="#使用-openssl-生成高强度密码" aria-label="Permalink to “使用 openssl 生成高强度密码”">​</a></h3><p>这里使用 openssl 的 rand 方法，它会生成一个 14 位字符的随机字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openssl rand -base64 14</span></span></code></pre></div><h3 id="使用-urandom-生成高强度密码" tabindex="-1">使用 urandom 生成高强度密码 <a class="header-anchor" href="#使用-urandom-生成高强度密码" aria-label="Permalink to “使用 urandom 生成高强度密码”">​</a></h3><p>这里我们将使用 <code>tr</code> 条件来过滤 <code>/dev/urandom</code> 的输出，从而删掉那些不想要的字符，并打印出第一个出现的 14 位字符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt; /dev/urandom tr -dc A-Za-z0-9 | head -c14; echo</span></span></code></pre></div><h3 id="使用-pwgen-生成高强度密码" tabindex="-1">使用 pwgen 生成高强度密码 <a class="header-anchor" href="#使用-pwgen-生成高强度密码" aria-label="Permalink to “使用 pwgen 生成高强度密码”">​</a></h3><p><code>pwgen</code> 是一个生成随机、无特殊含义但可以正常拼读的密码。</p><p>安装 <code>pwgen</code>，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install pwgen</span></span></code></pre></div><p>安装好之后，使用以下命令来生成一个 14 位随机字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pwgen 14 1</span></span></code></pre></div><p>你也可以使用以下标记：</p><ul><li>-c 或 --capitalize 生成的密码中至少包含一个大写字母</li><li>-A 或 --no-capitalize 生成的密码中不含大写字母</li><li>-n 或 --numerals 生成的密码中至少包含一个数字</li><li>-0 或 --no-numerals 生成的密码中不含数字</li><li>-y 或 --symbols 生成的密码中至少包含一个特殊字符</li><li>-s 或 --secure 生成一个完全随机的密码</li><li>-B 或 --ambiguous 生成的密码中不含易混淆字符 (ambiguous characters)</li><li>-h 或 --help 输出帮助信息</li><li>-H 或 --sha1=path/to/file[#seed] 使用指定文件的 sha1 哈希值作为随机生成器</li><li>-C 按列输出生成的密码</li><li>-1 不按列输出生成的密码</li><li>-v 或 --no-vowels 不使用任何元音，以免意外生成让人讨厌的单词</li></ul><h3 id="使用-gpg-生成高强度密码" tabindex="-1">使用 gpg 生成高强度密码 <a class="header-anchor" href="#使用-gpg-生成高强度密码" aria-label="Permalink to “使用 gpg 生成高强度密码”">​</a></h3><p>我们也可以使用 <code>gpg</code> 工具来生成一个 14 位字符的密码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gpg --gen-random --armor 1 14</span></span></code></pre></div><h3 id="其它方法" tabindex="-1">其它方法 <a class="header-anchor" href="#其它方法" aria-label="Permalink to “其它方法”">​</a></h3><p>当然，可能还有很多方法可以生成一个高强度密码。比方说，你可以添加以下 bash shell 方法到 <code>~/.bashrc</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>genpasswd() { </span></span>
<span class="line"><span>    strings /dev/urandom | grep -o &#39;[[:alnum:]]&#39; | head -n 14 | tr -d &#39;\\n&#39;; echo</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>当你想要生成一个高强度的随机密码时，运行 <code>genpasswd</code> 就好了。</p><hr>`,25)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),i(a,{href:"https://www.rosehosting.com/blog/generate-password-linux-command-line/"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.rosehosting.com/blog/generate-password-linux-command-line/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=s("作者：",-1)),i(a,{href:"www.rosehosting.com"},{default:t(()=>[...e[2]||(e[2]=[s("RoseHosting",-1)])]),_:1}),e[6]||(e[6]=s(" 译者：",-1)),i(a,{href:"https://github.com/GHLandy"},{default:t(()=>[...e[3]||(e[3]=[s("GHLandy",-1)])]),_:1}),e[7]||(e[7]=s(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[s("Linux中国",-1)])]),_:1}),e[12]||(e[12]=s(" 荣誉推出",-1))])])}const x=l(h,[["render",g]]);export{C as __pageData,x as default};
